// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doAnswer;

import java.util.Collections;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

import org.eclipse.kura.KuraException;
import org.junit.After;
import org.junit.Test;

public class EnforcementCloseDuringChecksTest extends AbstractEnforcementTest {

    private static final long TIMEOUT_SECONDS = 5;
    private static final long STILL_WAITING_MILLIS = 200;

    private final ExecutorService background = Executors.newCachedThreadPool();
    private final CountDownLatch removalStarted = new CountDownLatch(1);
    private final CountDownLatch removalReleased = new CountDownLatch(1);
    private Future<?> closing;

    @After
    public void releaseBackgroundWork() {
        this.removalReleased.countDown();
        this.background.shutdownNow();
    }

    @Test
    public void sweepStopsRemovingContainersOnceClosed() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainer(OTHER_CONTAINER_ID, IMAGE_DIGEST);
        givenRemovingTheContainerClosesEnforcement(CONTAINER_ID);

        whenEnforcementStarts();

        thenContainerWasDeleted(CONTAINER_ID);
        thenContainerWasNotDeleted(OTHER_CONTAINER_ID);
    }

    @Test
    public void checkInterruptedByCloseDoesNotRemoveTheContainer() throws KuraException {
        givenStartedEnforcement();
        givenImageLookupClosesEnforcement(CONTAINER_ID);

        whenStartEventArrivesFor(CONTAINER_ID);

        thenNoContainerWasDeleted();
    }

    @Test
    public void closeWaitsForTheRemovalInProgress() throws Exception {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerRemovalBlocksUntilReleased();
        givenRemovalInProgress();

        whenEnforcementClosesInBackground();

        thenCloseHasNotReturned();
    }

    @Test
    public void closeReturnsOnceTheRemovalInProgressCompletes() throws Exception {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerRemovalBlocksUntilReleased();
        givenRemovalInProgress();
        givenEnforcementClosingInBackground();

        whenRemovalCompletes();

        thenCloseReturned();
    }

    private void givenRemovingTheContainerClosesEnforcement(String containerId) throws KuraException {
        doAnswer(invocation -> {
            this.enforcement.close();
            return null;
        }).when(this.target).forceDeleteContainer(containerId);
    }

    private void givenImageLookupClosesEnforcement(String containerId) {
        doAnswer(invocation -> {
            this.enforcement.close();
            return Collections.singleton(IMAGE_DIGEST);
        }).when(this.target).getImageDigestsByContainerId(containerId);
    }

    private void givenContainerRemovalBlocksUntilReleased() throws KuraException {
        doAnswer(invocation -> {
            this.removalStarted.countDown();
            this.removalReleased.await(TIMEOUT_SECONDS, TimeUnit.SECONDS);
            return null;
        }).when(this.target).forceDeleteContainer(CONTAINER_ID);
    }

    private void givenRemovalInProgress() throws InterruptedException {
        this.background.execute(this::givenStartedEnforcement);
        assertTrue(this.removalStarted.await(TIMEOUT_SECONDS, TimeUnit.SECONDS));
    }

    private void givenEnforcementClosingInBackground() {
        this.closing = this.background.submit(this.enforcement::close);
    }

    private void whenEnforcementClosesInBackground() {
        this.closing = this.background.submit(this.enforcement::close);
    }

    private void whenRemovalCompletes() {
        this.removalReleased.countDown();
    }

    private void thenCloseHasNotReturned() {
        assertThrows(TimeoutException.class, () -> this.closing.get(STILL_WAITING_MILLIS, TimeUnit.MILLISECONDS));
    }

    private void thenCloseReturned() throws InterruptedException, ExecutionException, TimeoutException {
        this.closing.get(TIMEOUT_SECONDS, TimeUnit.SECONDS);
        assertTrue(this.closing.isDone());
    }
}
